mapper.select:
SELECT , CAST(NULL AS varchar) AS time FROM mrb01_booking t1 WHERE 1=1 AND DATE(t1.mrb01_booking_dt) = CAST(#{date} AS date) AND t1.mrb01_company_id = #{companyId}
AND t1.mrb01_emp_id = #{empId}
ORDER BY f_cdnm('MeetingRoomCode', t1.mrb01_room_cd, t1.mrb01_company_id, f_sysdate()) COLLATE "ko_KR.utf8", t1.mrb01_booking_dt

SELECT f_booking_check1( #{bookingId}
                       , #{roomCd}
                       , CAST(#{bookingDate} AS timestamp)
                       , #{startHour}
                       , #{startMin}
                       , #{closeHour}
                       , #{closeMin}
                       , #{companyId}
       ) AS mrb01_check_ok

mapper.delete:
DELETE FROM mrb01_booking
 WHERE mrb01_parent_id = #{parentId}
   AND mrb01_company_id = #{companyId}

DELETE FROM mrb01_booking
 WHERE mrb01_booking_id IN
#{id}
   AND mrb01_company_id = #{companyId}
